"""把多行 JSON 日志按小时聚合成统计表，输出 CSV。"""
import json
from collections import defaultdict
from datetime import datetime

def parse_json_line(line):
    """解析单行 JSON 字符串。"""
    try:
        return json.loads(line)
    except json.JSONDecodeError as e:
        print(f"警告：跳过无效日志行: {e}")
        return None

def extract_hour(log_entry):
    """从日志条目提取小时字段。"""
    if not isinstance(log_entry, dict):
        raise ValueError("日志条目必须是字典类型")
    timestamp = log_entry.get('timestamp')
    if not timestamp:
        raise ValueError("日志条目缺少 'timestamp' 字段")
    try:
        dt = datetime.fromisoformat(timestamp.replace('Z', '+00:00'))
        return dt.hour
    except (ValueError, AttributeError) as e:
        print(f"警告：无法解析时间 {timestamp}: {e}")
        return None

def aggregate_logs(log_lines):
    """按小时聚合日志条目。"""
    hourly_counts = defaultdict(int)
    for line in log_lines:
        entry = parse_json_line(line)
        if entry is not None:
            hour = extract_hour(entry)
            if hour is not None:
                hourly_counts[hour] += 1
    return dict(hourly_counts)

def write_csv(data, filename):
    """将聚合结果写入 CSV 文件。"""
    import csv
    with open(filename, 'w', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['hour', 'count'])
        for hour in sorted(data.keys()):
            writer.writerow([hour, data[hour]])

def main():
    """主入口：读取日志文件，聚合并输出 CSV。"""
    input_file = 'logs.jsonl'
    output_file = 'aggregated.csv'
    with open(input_file, 'r') as f:
        log_lines = f.readlines()
    aggregated = aggregate_logs(log_lines)
    write_csv(aggregated, output_file)

if __name__ == '__main__':
    main()

"""日志聚合器：按时间范围、字段过滤和时区跨越聚合日志条目。"""
import os
from datetime import datetime, timezone, timedelta

# 定义日志条目结构
class LogEntry:
    def __init__(self, timestamp: str, level: str, message: str):
        self.timestamp = timestamp
        self.level = level
        self.message = message

    def to_dict(self) -> dict:
        return {
            "timestamp": self.timestamp,
            "level": self.level,
            "message": self.message
        }

# 定义日志聚合器类
class LogAggregator:
    def __init__(self, start_time: str = None, end_time: str = None):
        self.start_time = datetime.fromisoformat(start_time).replace(tzinfo=timezone.utc) if start_time else timezone.utc
        self.end_time = datetime.fromisoformat(end_time).replace(tzinfo=timezone.utc) if end_time else timezone.utc

    def add_entry(self, entry: LogEntry):
        now = datetime.now(timezone.utc)
        if self.start_time <= now <= self.end_time:
            self.entries.append(entry.to_dict())

    def filter_by_level(self, level: str) -> list:
        return [e for e in self.entries if e["level"] == level]

    def filter_by_message(self, message: str) -> list:
        return [e for e in self.entries if message.lower() in e["message"].lower()]

    def filter_by_timestamp_range(self, start_str: str, end_str: str):
        start = datetime.fromisoformat(start_str).replace(tzinfo=timezone.utc)
        end = datetime.fromisoformat(end_str).replace(tzinfo=timezone.utc)
        return [e for e in self.entries if start <= e["timestamp"] <= end]

    def aggregate_by_level(self) -> dict:
        counts = {}
        for entry in self.entries:
            level = entry["level"]
            counts[level] = counts.get(level, 0) + 1
        return counts

# 主入口函数
if __name__ == "__main__":
    aggregator = LogAggregator()
    print("日志聚合器已初始化。")

"""解析日志文件并输出聚合结果。"""
import os
from typing import List, Tuple

def parse_log_line(line: str) -> Tuple[str, str]:
    """将单行日志拆分为时间戳和内容。"""
    parts = line.split(' ', 1)
    if len(parts) != 2:
        return ('', '')
    return (parts[0], parts[1])


def aggregate_logs(log_file: str) -> List[Tuple[str, int]]:
    """读取日志文件，统计每条内容出现的次数。"""
    counts = {}
    with open(log_file, 'r', encoding='utf-8') as f:
        for line in f:
            timestamp, content = parse_log_line(line)
            if not content:
                continue
            counts[content] = counts.get(content, 0) + 1
    return list(counts.items())


if __name__ == '__main__':
    import sys
    log_file = sys.argv[1] if len(sys.argv) > 1 else 'log.txt'
    results = aggregate_logs(log_file)
    for content, count in results:
        print(f"{content}: {count}")

