import os
from typing import List, Tuple

class Router:
    def __init__(self):
        self.routes: List[Tuple[str, str]] = []

    def add_route(self, path: str, method: str) -> None:
        """Add a route to the router."""
        self.routes.append((path, method))

    def match(self, url_path: str, request_method: str = 'GET') -> Tuple[str, str]:
        """Match URL path and request method against registered routes."""
        for route_path, route_method in self.routes:
            if route_method == request_method and url_path.startswith(route_path):
                return (url_path, route_method)
        return ('', '')


if __name__ == "__main__":
    router = Router()
    router.add_route('/about', 'GET')
    router.add_route('/user/<id>', 'GET')
    print(router.match('/about'))
    print(router.match('/user/123', 'GET'))

