import os
import hashlib
from pathlib import Path


def get_file_hash(file_path):
    """获取文件的 SHA-256 哈希值。"""
    sha256 = hashlib.sha256()
    try:
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(8192), b''):
                sha256.update(chunk)
        return sha256.hexdigest()
    except Exception:
        return None


def find_duplicates(root_dir):
    """扫描目录，返回重复文件列表。"""
    file_map = {}
    for path in Path(root_dir).rglob('*'):
        if path.is_file():
            h = get_file_hash(path)
            if h is None:
                continue
            key = (h, str(path.parent))
            if key in file_map:
                yield file_map[key], path
            else:
                file_map[key] = path


def main():
    import argparse
    parser = argparse.ArgumentParser(description='扫描重复文件')
    parser.add_argument('dir', help='要扫描的目录')
    parser.add_argument('--dry-run', action='store_true', help='只打印不删除')
    parser.add_argument('--json', action='store_true', help='以 JSON 输出')
    args = parser.parse_args()

    duplicates = list(find_duplicates(args.dir))
    if args.json:
        import json
        print(json.dumps([{'file1': str(d[0]), 'file2': str(d[1])} for d in duplicates]))
    else:
        for f1, f2 in duplicates:
            print(f'{f1} == {f2}')

if __name__ == '__main__':
    main()

import os
import hashlib
from collections import defaultdict

# 按文件大小分组，避免大文件一次性读入内存
class HashProcessor:
    def __init__(self, chunk_size=1024 * 1024):
        self.chunk_size = chunk_size
        self.hash_groups = defaultdict(list)

    def process_file(self, filepath):
        """按文件大小分组处理，避免大文件一次性读入内存。"""
        size = os.path.getsize(filepath)
        group_key = f"{size // (self.chunk_size // 1024)}MB" if size >= self.chunk_size else "0MB"

        with open(filepath, 'rb') as f:
            while True:
                chunk = f.read(self.chunk_size)
                if not chunk:
                    break
                h = hashlib.md5(chunk).hexdigest()
                self.hash_groups[group_key].append(h)

    def get_hash_counts(self):
        """返回每个分组内的哈希出现次数。"""
        return {k: len(v) for k, v in self.hash_groups.items()}

if __name__ == '__main__':
    processor = HashProcessor()
    # 示例：处理当前目录下所有 .txt 文件
    for root, dirs, files in os.walk('.'):
        for file in files:
            if file.endswith('.txt'):
                processor.process_file(os.path.join(root, file))
    print(processor.get_hash_counts())

"""数据清洗工具：读取 CSV、处理缺失值与重复行、输出规范 CSV。"""
import csv
from datetime import datetime

def read_csv(file_path):
    """读取 CSV，返回列表（每行是字符串列表）。"""
    rows = []
    with open(file_path, 'r', encoding='utf-8') as f:
        reader = csv.reader(f)
        for row in reader:
            rows.append(row)
    return rows

def clean_rows(rows):
    """删除完全重复的行。"""
    seen = set()
    cleaned = []
    for row in rows:
        key = tuple(row)
        if key not in seen:
            seen.add(key)
            cleaned.append(row)
    return cleaned

def fix_date(date_str):
    """尝试将日期字符串转为标准格式。"""
    try:
        datetime.strptime(date_str, '%Y-%m-%d')
        return date_str
    except ValueError:
        return None

def write_csv(file_path, rows):
    """写入 CSV，处理缺失值（空字符串替换为 NaN）。"""
    with open(file_path, 'w', encoding='utf-8', newline='') as f:
        writer = csv.writer(f)
        for row in rows:
            cleaned_row = []
            for cell in row:
                if cell is None or cell == '':
                    cleaned_row.append('NaN')
                else:
                    cleaned_row.append(cell)
            writer.writerow(cleaned_row)

if __name__ == '__main__':
    import sys
    input_file = sys.argv[1] if len(sys.argv) > 1 else 'input.csv'
    output_file = 'output.csv'
    rows = read_csv(input_file)
    cleaned_rows = clean_rows(rows)
    fixed_rows = []
    for row in cleaned_rows:
        new_row = []
        for cell in row:
            if isinstance(cell, str) and len(new_row) == 0 or (isinstance(cell, str) and cell.strip() != ''):
                pass
            else:
                new_row.append('NaN')
            # 此处简化处理：直接保留原值，仅在空字符串时替换为 NaN
        fixed_rows.append(new_row)
    write_csv(output_file, fixed_rows)

"""清洗脚本：读取 CSV、处理日期与金额、输出清洗后 CSV。"""
import csv
from datetime import datetime

def parse_date(date_str):
    """解析日期字符串，返回 datetime 对象。"""
    for fmt in ['%Y-%m-%d', '%Y/%m/%d', '%Y.%m.%d']:
        try:
            return datetime.strptime(date_str, fmt)
        except ValueError:
            continue
    raise ValueError(f'无法解析日期: {date_str}')

def parse_amount(amount_str):
    """解析金额字符串，返回浮点数。"""
    amount_str = amount_str.replace('$', '').replace(',', '')
    try:
        return float(amount_str)
    except ValueError:
        raise ValueError(f'无法解析金额: {amount_str}')

def clean_row(row):
    """清洗单行数据。"""
    date = parse_date(row.get('date'))
    amount = parse_amount(row.get('amount'))
    return {'date': date, 'amount': amount}

def main():
    input_file = 'input.csv'
    output_file = 'output.csv'

    with open(input_file, newline='', encoding='utf-8') as f_in:
        reader = csv.DictReader(f_in)
        rows = list(reader)

    cleaned_rows = [clean_row(row) for row in rows]

    with open(output_file, 'w', newline='', encoding='utf-8') as f_out:
        writer = csv.writer(f_out)
        writer.writerow(['date', 'amount'])
        for row in cleaned_rows:
            writer.writerow([row['date'].strftime('%Y-%m-%d'), row['amount']])

if __name__ == '__main__':
    main()

"""修复带 BOM 的 UTF-8 文件读取问题。"""
import sys
from pathlib import Path

def read_file_with_bom(file_path):
    """读取文件并去除前导 BOM（如果存在）。"""
    with open(file_path, 'rb') as f:
        content = f.read()
    if content.startswith(b'\xef\xbb\xbf'):
        return content[3:].decode('utf-8')
    else:
        return content.decode('utf-8')

if __name__ == '__main__':
    file_path = sys.argv[1] if len(sys.argv) > 1 else 'test.txt'
    print(read_file_with_bom(file_path))

"""任务管理器：提供增删改查接口与请求体校验"""
import json
from http.server import BaseHTTPRequestHandler, HTTPServer

class TaskManager(BaseHTTPRequestHandler):
    tasks = []

    def do_POST(self):
        content_length = int(self.headers['Content-Length'])
        body = self.rfile.read(content_length)
        try:
            data = json.loads(body.decode('utf-8'))
        except json.JSONDecodeError:
            self.send_response(400)
            self.end_headers()
            self.wfile.write(b'Invalid JSON')
            return

        if not isinstance(data, dict):
            self.send_response(400)
            self.end_headers()
            self.wfile.write(b'Expected object')
            return

        action = data.get('action', '')
        task_id = data.get('id', None)
        title = data.get('title', '')
        status = data.get('status', 'pending')

        if action == 'create':
            self._store_task(data, 'created')
        elif action == 'read':
            self._read_task(task_id)
        elif action == 'update':
            self._update_task(task_id, data)
        elif action == 'delete':
            self._delete_task(task_id)

    def _store_task(self, data, status):
        task = {'id': data.get('id'), 'title': data['title'], 'status': status}
        if not isinstance(data['title'], str) or len(data['title']) > 100:
            self.send_response(400)
            self.end_headers()
            self.wfile.write(b'Invalid title')
            return
        self.tasks.append(task)

    def _read_task(self, task_id):
        for t in self.tasks:
            if t['id'] == task_id:
                self.send_response(200)
                body = json.dumps({'id': t['id'], 'title': t['title'], 'status': t['status']})
                self.end_headers()
                self.wfile.write(body.encode('utf-8'))
                return
        self.send_response(404)
        self.end_headers()
        self.wfile.write(b'Task not found')

    def _update_task(self, task_id, data):
        for t in self.tasks:
            if t['id'] == task_id:
                t['title'] = data.get('title', '')
                t['status'] = data.get('status', 'pending')
                break

    def _delete_task(self, task_id):
        self.tasks = [t for t in self.tasks if t['id'] != task_id]

    def send_error(self, code, message=None):
        body = json.dumps({'error': message or 'Internal Server Error'})
        self.send_response(code)
        self.end_headers()
        self.wfile.write(body.encode('utf-8'))

if __name__ == '__main__':
    HTTPServer(('', 8000), TaskManager).serve_forever()

"""并发数据结构示例：线程安全队列与缓存"""
import threading
from collections import deque

class ThreadSafeQueue:
    """线程安全的先进先出队列"""
    def __init__(self):
        self._queue = deque()
        self._lock = threading.Lock()

    def put(self, item):
        with self._lock:
            self._queue.append(item)

    def get(self):
        with self._lock:
            if not self._queue:
                return None
            return self._queue.popleft()

class ThreadSafeCache:
    """线程安全的缓存结构"""
    def __init__(self, max_size=100):
        self._cache = {}
        self._max_size = max_size
        self._lock = threading.Lock()

    def get(self, key):
        with self._lock:
            if key in self._cache:
                return self._cache[key]
            return None

    def put(self, key, value):
        with self._lock:
            if len(self._cache) >= self._max_size:
                # 移除最旧的条目（这里用 FIFO 实现）
                oldest_key = next(iter(self._cache))
                del self._cache[oldest_key]
            self._cache[key] = value

if __name__ == "__main__":
    q = ThreadSafeQueue()
    c = ThreadSafeCache(max_size=3)
    print(q.put("a"))
    print(c.put("b", 1))
    print(c.get("b"))
    print(q.get())

import os
import time
from pathlib import Path

# ---------- 数据结构 ----------
def _task_file(path):
    """读取单个任务文件的元数据。"""
    if not Path(path).is_file():
        raise FileNotFoundError(f"Task file not found: {path}")
    with open(path, 'rb') as f:
        data = f.read()
    return {"name": "task", "data": data}

# ---------- 核心函数 ----------
def _process_task(task):
    """处理单个任务。返回 True 表示成功，False 表示失败。"""
    try:
        # 模拟处理逻辑：若数据以 b'fail' 开头则视为失败
        if task["data"].startswith(b"fail"):
            raise RuntimeError("Task processing failed")
        return True
    except Exception as e:
        print(f"Processing error: {e}")
        return False

# ---------- 队列 worker 主逻辑 ----------
def _worker(dir_path, archive_dir, deadletter_dir):
    """从目录取任务文件、按顺序处理、失败重试 3 次后进死信。"""
    task_files = sorted(Path(dir_path).glob("*.py"))
    retry_count = {}

    for tf in task_files:
        attempt = 0
        while attempt <= 3:
            try:
                task = _task_file(tf)
                if _process_task(task):
                    # 处理成功：归档文件
                    Path(archive_dir).mkdir(parents=True, exist_ok=True)
                    with open(f"{tf.name}.processed", "wb") as f:
                        f.write(task["data"])
                    print(f"Processed: {tf}")
                    break
                else:
                    # 处理失败：重试或进死信
                    attempt += 1
            except Exception as e:
                attempt += 1
        if attempt > 3:
            Path(deadletter_dir).mkdir(parents=True, exist_ok=True)
            with open(f"{tf.name}.dead", "wb") as f:
                f.write(b"Dead letter: retry exceeded")
            print(f"Dead letter: {tf}")

# ---------- 入口 ----------
def main():
    """直接运行 worker。"""
    base_dir = Path.cwd()
    task_dir = base_dir / "tasks"
    archive_dir = base_dir / "archive"
    deadletter_dir = base_dir / "deadletter"

    _worker(task_dir, archive_dir, deadletter_dir)

if __name__ == "__main__":
    main()

"""把多行 JSON 日志按小时聚合成统计表，输出 CSV。"""
import json
from datetime import datetime, timedelta

def parse_json_log(file_path):
    """读取并解析 JSON 格式日志文件。"""
    logs = []
    with open(file_path, 'r', encoding='utf-8') as f:
        for line in f:
            if line.strip():
                try:
                    log_entry = json.loads(line)
                    logs.append(log_entry)
                except json.JSONDecodeError:
                    continue
    return logs

def aggregate_by_hour(logs):
    """按小时聚合日志条目。"""
    hourly_counts = {}
    for log in logs:
        timestamp_str = log.get('timestamp', '')
        if not isinstance(timestamp_str, str):
            continue
        try:
            dt = datetime.fromisoformat(timestamp_str.replace('Z', '+00:00'))
        except ValueError:
            continue
        hour_key = dt.strftime('%Y-%m-%d %H')
        hourly_counts[hour_key] = hourly_counts.get(hour_key, 0) + 1
    return hourly_counts

def write_csv(hourly_counts, output_path):
    """将聚合结果写入 CSV 文件。"""
    import csv
    with open(output_path, 'w', newline='', encoding='utf-8') as f:
        writer = csv.writer(f)
        writer.writerow(['hour', 'count'])
        for hour in sorted(hourly_counts.keys()):
            writer.writerow([hour, hourly_counts[hour]])

def main():
    """主入口：读取日志，聚合，按小时输出 CSV。"""
    input_file = 'logs.json'
    output_file = 'hourly_stats.csv'
    logs = parse_json_log(input_file)
    hourly_counts = aggregate_by_hour(logs)
    write_csv(hourly_counts, output_file)

if __name__ == '__main__':
    main()

"""日志聚合脚本：读取本地文件，按行拆分并过滤乱码行，输出清洗后的日志到 stdout。"""
import sys
from typing import List, Tuple

# 定义日志记录的字段名（与输入格式保持一致）
LOG_FIELDS = ["timestamp", "level", "message"]


def parse_log_line(line: str) -> Tuple[str, str, str]:
    """解析单行日志，返回 (timestamp, level, message)。"""
    # 去除首尾空白字符
    line = line.strip()
    if not line:
        return ("", "", "")

    # 按空格分割，最多切到3个字段（时间、级别、消息）
    parts = line.split(" ", 2)
    timestamp, level, message = (parts[0], parts[1], parts[2]) if len(parts) >= 3 else ("", "", "")
    return (timestamp, level, message)


def is_garbled_line(line: str) -> bool:
    """判断一行是否为乱码行。"""
    # 简单规则：包含非 ASCII 字符或出现连续空格
    try:
        line.encode("ascii")
    except UnicodeEncodeError:
        return True

    if "  " in line or "\t" in line:
        return True
    return False


def aggregate_logs(input_path: str, output_stream) -> None:
    """读取输入文件，解析并过滤日志行，将清洗后的日志输出到指定流。"""
    with open(input_path, "r", encoding="utf-8") as f:
        for line in f:
            if is_garbled_line(line):
                continue
            timestamp, level, message = parse_log_line(line)
            print(f"{timestamp} {level} {message}", end="")


if __name__ == "__main__":
    # 支持两种调用方式：直接指定文件路径，或从 stdin 读取
    if len(sys.argv) > 1:
        input_path = sys.argv[1]
        aggregate_logs(input_path, sys.stdout)
    else:
        for line in sys.stdin:
