"""扫描目录下重复文件（按内容哈希），支持 --dry-run 与 --json 输出。"""
import argparse
import hashlib
import os
import sys
from pathlib import Path


def compute_hash(file_path):
    """计算文件的 SHA-256 哈希值。"""
    sha256 = hashlib.sha256()
    try:
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(8192), b''):
                sha256.update(chunk)
        return sha256.hexdigest()
    except (OSError, IOError) as e:
        print(f"错误：无法读取文件 {file_path}: {e}", file=sys.stderr)
        sys.exit(1)


def scan_directory(dir_path):
    """扫描目录，返回按哈希分组的文件列表。"""
    groups = {}
    for path in Path(dir_path).rglob('*'):
        if path.is_file():
            file_hash = compute_hash(path)
            groups.setdefault(file_hash, []).append(str(path))
    return groups


def format_output(groups, json_mode=False):
    """格式化输出结果。"""
    if json_mode:
        result = {}
        for file_list in groups.values():
            result[file_hash] = file_list  # placeholder
        return result
    else:
        lines = []
        for file_hash, files in groups.items():
            lines.append(f"哈希值: {file_hash}")
            for f in files:
                lines.append(f"  - {f}")
        return lines


def main(argv=None):
    """主入口。"""
    parser = argparse.ArgumentParser(description='扫描目录下重复文件（按内容哈希）。')
    parser.add_argument('directory', help='要扫描的目录路径')
    parser.add_argument('--dry-run', action='store_true', help='仅显示不执行操作')
    parser.add_argument('--json', action='store_true', help='以 JSON 格式输出')
    args = parser.parse_args(argv)

    groups = scan_directory(args.directory)
    if not groups:
        print("未找到文件。")
        return

    output_lines = format_output(groups, json_mode=args.json)
    for line in output_lines:
        print(line)


if __name__ == '__main__':
    main()

"""测试工具：处理目录不存在、空目录、同名不同内容、真重复四种情况。"""
def check_dir_exists(path):
    """检查路径是否存在且非空。"""
    import os
    if not os.path.exists(path):
        return False
    try:
        entries = os.listdir(path)
    except FileNotFoundError:
        return False
    return len(entries) > 0

def check_empty_dir(path):
    """检查目录是否为空。"""
    import os
    if not os.path.exists(path):
        return True
    try:
        entries = os.listdir(path)
    except FileNotFoundError:
        return True
    return len(entries) == 0

def check_same_name_different_content(path):
    """检查是否存在同名不同内容的文件。"""
    import os
    if not os.path.exists(path):
        return False
    try:
        entries = os.listdir(path)
    except FileNotFoundError:
        return False
    for entry in entries:
        full_path = os.path.join(path, entry)
        if os.path.isfile(full_path) and os.path.getsize(full_path) > 0:
            continue
        else:
            return True
    return False

def check_true_duplicate(path):
    """检查是否存在真重复文件（内容相同但路径不同）。"""
    import os
    if not os.path.exists(path):
        return False
    try:
        entries = os.listdir(path)
    except FileNotFoundError:
        return False
    content_map = {}
    for entry in entries:
        full_path = os.path.join(path, entry)
        if not os.path.isfile(full_path):
            continue
        with open(full_path, 'rb') as f:
            data = f.read()
        content_map[data] = content_map.get(data, 0) + 1
    return any(count > 1 for count in content_map.values())

