"""清洗 CSV 数据：处理缺失值、重复行与日期格式混乱。"""
import csv
from datetime import datetime

def load_csv(filepath):
    """读取 CSV 文件，返回列表（每行是字符串）。"""
    with open(filepath, 'r', encoding='utf-8') as f:
        reader = csv.reader(f)
        return [row for row in reader]


def clean_rows(rows):
    """删除重复行，处理缺失值。"""
    seen = set()
    cleaned = []
    for row in rows:
        if len(row) < 3:  # 行太短，直接丢弃
            continue
        key = tuple(cell.strip() if cell else '' for cell in row)
        if key not in seen:
            seen.add(key)
            cleaned.append(row)
    return cleaned


def normalize_date(date_str):
    """将日期字符串转为标准格式 YYYY-MM-DD。"""
    formats = ['%Y-%m-%d', '%Y/%m/%d', '%d-%m-%Y']
    for fmt in formats:
        try:
            return datetime.strptime(date_str.strip(), fmt).strftime('%Y-%m-%d')
        except ValueError:
            continue
    raise ValueError(f"无法解析日期：{date_str}")


def write_csv(filepath, rows):
    """写入规范 CSV，列名固定为 ['ID', 'Name', 'Date']。"""
    with open(filepath, 'w', encoding='utf-8', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['ID', 'Name', 'Date'])
        for row in rows:
            if len(row) >= 3:
                writer.writerow([row[0], row[1], normalize_date(row[2])])


def main():
    """主入口：读取 → 清洗 → 输出。"""
    input_path = 'input.csv'
    output_path = 'output.csv'
    rows = load_csv(input_path)
    cleaned = clean_rows(rows)
    write_csv(output_path, cleaned)


if __name__ == '__main__':
    main()

"""清洗 CSV 数据：处理表头、日期跨格式、金额千分位与空值。"""
import os
from datetime import datetime

# ---------- 数据结构 ----------
def _parse_date(s):
    """解析日期字符串，返回 datetime 或 None。"""
    if not s:
        return None
    for fmt in ("%Y-%m-%d", "%Y/%m/%d", "%Y.%m.%d", "%d-%m-%Y", "%d/%m/%Y", "%d.%m.%Y"):
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            continue
    return None


def _parse_amount(s):
    """解析金额字符串，返回 float 或 None。"""
    if not s:
        return None
    try:
        return float(s.replace(" ", "").replace("K", "").replace("M", ""))
    except ValueError:
        return None


def _clean_row(row):
    """清洗一行数据，返回新列表。"""
    cleaned = []
    for cell in row:
        if not isinstance(cell, str):
            continue
        s = cell.strip()
        if s == "":
            continue
        if _parse_date(s) is None and _parse_amount(s) is None:
            cleaned.append("")
        else:
            cleaned.append(s)
    return cleaned


def load_csv(path):
    """读取 CSV 文件，返回列表的列表。"""
    rows = []
    with open(path, "r", encoding="utf-8") as f:
        reader = __import__("csv").reader(f)
        for row in reader:
            if not any(cell.strip() for cell in row):
                continue
            rows.append(row)
    return rows


def clean_csv(path, out_path):
    """清洗 CSV 文件并写入新文件。"""
    data = load_csv(path)
    cleaned = [_clean_row(r) for r in data]
    with open(out_path, "w", encoding="utf-8-sig") as f:
        writer = __import__("csv").writer(f)
        writer.writerows(cleaned)


def main():
    import sys
    if len(sys.argv) < 3:
        print("用法：python cleaner.py <输入文件> <输出文件>")
        return
    clean_csv(sys.argv[1], sys.argv[2])


if __name__ == "__main__":
    main()

def clean_script():
    import os
    def read_file(path):
        with open(path, 'r', encoding='utf-8-sig') as f:
            return f.read()
    def process_data(data):
        lines = data.split('\n')
        cleaned_lines = []
        for line in lines:
            if not line.strip():
