"""任务队列 worker：读取目录中的任务文件，按顺序处理，失败重试后归档至死信目录。"""
import os
import time
from pathlib import Path

# 配置路径
WORK_DIR = Path("/data/tasks")
LOG_DIR = Path("/data/logs")
DELAY_DIR = Path("/data/delay")
DISMISSED_DIR = Path("/data/discharged")
DEAD_LET_DIR = Path("/data/dead_let")

# 确保目录存在
for d in [WORK_DIR, LOG_DIR, DELAY_DIR, DISMISSED_DIR, DEAD_LET_DIR]:
    d.mkdir(parents=True, exist_ok=True)


def load_task_file(file_path):
    """加载任务文件内容。"""
    with open(file_path, "r", encoding="utf-8") as f:
        return f.read()


def process_task(task_content):
    """处理单个任务，返回结果或异常。"""
    # 示例处理逻辑：判断是否包含关键字 "urgent"
    if "urgent" in task_content.lower():
        print("Processing urgent task...")
        return {"status": "success", "message": "Urgent task completed."}
    else:
        raise ValueError("Task processing failed: missing required keyword.")


def write_result(result):
    """将处理结果写入日志目录。"""
    log_file = LOG_DIR / f"result_{result['status']}.txt"
    with open(log_file, "w", encoding="utf-8") as f:
        f.write(f"Status: {result['status']}\nMessage: {result.get('message', '')}")


def retry_once(task_content):
    """重试一次处理。"""
    try:
        return process_task(task_content)
    except Exception as e:
        print(f"Retry 1 failed: {e}")
        raise


def main():
    """主循环：按顺序读取任务文件并处理。"""
    task_files = sorted(WORK_DIR.glob("*.txt"))
    if not task_files:
        print("No tasks found.")
        return

    for file_path in task_files:
        try:
            task_content = load_task_file(file_path)
            result = retry_once(task_content)
            write_result(result)
            print(f"Processed {file_path.name}")
        except Exception as e:
            print(f"Failed to process {file_path.name}: {e}")
            # 失败重试 3 次
            for attempt in range(1, 4):
                try:
                    result = retry_once(task_content)
                    write_result(result)
                    print(f"Processed {file_path.name} after retry {attempt}")
                    break
                except Exception as e2:
                    print(f"Retry {attempt} failed: {e2}")
            else:
                # 全部重试失败，归档至死信目录
                dead_file = DEAD_LET_DIR / f"{file_path.name}.txt"
                with open(dead_file, "w", encoding="utf-8") as f:
                    f.write(f"Failed after {3} retries: {e}")
                print(f"Archived failed task to dead letter: {dead_file}")


if __name__ == "__main__":
    main()

