"""日志聚合脚本：按时间范围过滤并统计各服务器的日志条目数。"""
import os
from datetime import datetime, timezone

# 配置区
CONFIG = {
    "start_time": "2024-01-01T00:00:00+08:00",
    "end_time": "2024-12-31T23:59:59+08:00",
    "log_dir": "."
}

# 数据结构区：日志条目类
class LogEntry:
    def __init__(self, timestamp_str, level, message):
        self.timestamp = datetime.fromisoformat(timestamp_str.replace("Z", "+00:00"))
        self.level = level
        self.message = message

# 核心函数区：读取并过滤日志

def read_logs(log_dir):
    """读取指定目录下所有 .log 文件，返回 LogEntry 列表。"""
    entries = []
    for root, _, files in os.walk(log_dir):
        for fname in files:
            if not fname.endswith(".log"):
                continue
            path = os.path.join(root, fname)
            with open(path, "r", encoding="utf-8") as f:
                for line in f:
                    line = line.strip()
                    if not line or ":" not in line:
                        continue
                    ts_str, _, msg = line.partition(":")
                    try:
                        entry = LogEntry(ts_str, "INFO", msg)
                        entries.append(entry)
                    except Exception as e:
                        print(f"跳过无效行: {line[:50]}")
    return entries

# 核心函数区：按时间范围过滤并统计

def filter_and_count(log_entries, start_time_str, end_time_str):
    """按配置的时间范围过滤日志条目，返回字典 {服务器名: 计数}。"""
    result = {}
    for entry in log_entries:
        if start_time_str <= entry.timestamp <= end_time_str:
            server_name = os.path.basename(os.path.dirname(entry.timestamp))
            # 注意：实际服务器名应从日志内容中提取，此处为简化处理
            result[server_name] = result.get(server_name, 0) + 1
    return result

# main 入口区

def main():
    """主函数：读取、过滤并统计日志。"""
    log_entries = read_logs(CONFIG["log_dir"])
    counts = filter_and_count(log_entries, CONFIG["start_time"], CONFIG["end_time"])
    print(f"{'服务器':<20} {'计数':>10}")
    for server, count in sorted(counts.items()):
        print(f"{server:<20} {count:>10}")

if __name__ == "__main__":
    main()

