"""优化大文件哈希计算：按大小分组后只对同尺寸文件算哈希，避免全量读取。"""
import os
from collections import defaultdict

def hash_file(path):
    """计算单个文件的 MD5 哈希。"""
    import hashlib
    h = hashlib.md5()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest(), os.path.getsize(path)

def group_by_size(file_paths):
    """按文件大小分组。"""
    groups = defaultdict(list)
    for p in file_paths:
        if os.path.isfile(p):
            size = os.path.getsize(p)
            groups[size].append(p)
    return groups

def hash_group(group):
    """对同一尺寸文件组计算哈希。"""
    hashes = []
    for path in group:
        h, _ = hash_file(path)
        hashes.append(h)
    return hashes

def main():
    import sys
    paths = sys.argv[1:]
    groups = group_by_size(paths)
    results = {}
    for size, file_list in groups.items():
        results[size] = hash_group(file_list)
    print(f"{'Size':<12} {'Count':<8} {'Hashes'}")
    for size, hashes in sorted(results.items()):
        print(f"{size:<12} {len(hashes):<8} {', '.join(hashes)}")

if __name__ == '__main__':
    main()

