"""队列 worker 实现：处理任务、限流、重试与死信。"""
import time
from typing import List, Optional, Tuple

class Task:
    """任务数据类。"""
    def __init__(self, id: int, payload: str):
        self.id = id
        self.payload = payload

class QueueWorker:
    """队列 worker 实现：处理任务、限流、重试与死信。"""
    def __init__(self, max_workers: int = 1):
        self.max_workers = max_workers
        self.tasks: List[Task] = []
        self.queued_tasks: List[Task] = []
        self.processed_tasks: List[Task] = []
        self.retries: int = 0
        self.timeout: float = 1.0
        self.lock = None
    def add_task(self, task_id: int, payload: str) -> bool:
        """添加任务到队列。返回 False 表示队列已满。"""
        if len(self.tasks) >= self.max_workers:
            return False
        new_task = Task(task_id, payload)
        self.tasks.append(new_task)
        return True
    def process_tasks(self):
        """处理队列中的任务。返回已处理的 task 数量。"""
        processed_count = 0
        for _ in range(len(self.tasks)):
            if not self.tasks:
                break
            current_task = self.tasks.pop(0)
            try:
                time.sleep(self.timeout)  # 模拟处理耗时
                self.processed_tasks.append(current_task)
                processed_count += 1
            except Exception as e:
                print(f"任务 {current_task.id} 处理失败: {e}")
        return processed_count
    def handle_timeout(self):
        """处理超时任务。"""
        for task in self.tasks[:]:
            if time.time() - task.payload > self.timeout:
                print(f"任务 {task.id} 已超时，重试中...")
                self.retries += 1
    def handle_retry_exhausted(self):
        """处理重试耗尽进死信。"""
        for task in self.tasks[:]:
            print(f"任务 {task.id} 重试耗尽，标记为死信。")
