"""扫描目录下的重复文件（按内容哈希），支持 --dry-run 与 --json 输出。"""
import argparse
import hashlib
import os
from pathlib import Path

def compute_hash(filepath):
    """计算文件的 SHA-256 哈希值。"""
    h = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest()


def find_duplicates(root_dir, dry_run=False, json_output=False):
    """查找根目录下内容相同的文件对。"""
    from collections import defaultdict
    groups = defaultdict(list)
    for path in Path(root_dir).rglob('*'):
        if path.is_file():
            hash_val = compute_hash(path)
            groups[hash_val].append(str(path))
    duplicates = {k: v for k, v in groups.items() if len(v) > 1}
    return duplicates


def main(argv=None):
    """命令行入口。"""
    parser = argparse.ArgumentParser(description='扫描目录下的重复文件')
    parser.add_argument('directory', help='要扫描的根目录')
    parser.add_argument('--dry-run', action='store_true', help='不实际删除，仅列出')
    parser.add_argument('--json', action='store_true', help='以 JSON 格式输出')
    args = parser.parse_args(argv)

    duplicates = find_duplicates(args.directory, dry_run=args.dry_run, json_output=args.json)

    if json_output:
        import json
        print(json.dumps(duplicates, indent=2))
    else:
        for hash_val, paths in duplicates.items():
            print(f'哈希值: {hash_val}')
            for path in paths:
                print(path)


if __name__ == '__main__':
    main()

"""测试工具：验证目录是否存在、是否为空、是否有同名不同内容文件、以及是否存在真重复文件。"""
import os
import sys

def check_dir_exists(path):
    """检查路径是否存在且是目录。"""
    return os.path.exists(path) and os.path.isdir(path)

def is_empty_dir(dir_path):
    """判断目录是否为空（无文件、无子目录）。"""
    if not check_dir_exists(dir_path):
        return False
    for entry in os.listdir(dir_path):
        full_path = os.path.join(dir_path, entry)
        if os.path.isdir(full_path) or os.path.isfile(full_path):
            return False
    return True

def has_same_name_different_content(path_dir):
    """检查目录下是否存在同名但内容不同的文件。"""
    files = []
    for entry in os.listdir(path_dir):
        full_path = os.path.join(path_dir, entry)
        if os.path.isfile(full_path):
            files.append((entry, open(full_path).read()))
    seen = {}
    for name, content in files:
        if name not in seen:
            seen[name] = content
        elif seen[name] != content:
            return True
    return False

def has_true_duplicate(path_dir):
    """检查目录下是否存在内容完全相同的文件对。"""
    file_contents = {}
    for entry in os.listdir(path_dir):
        full_path = os.path.join(path_dir, entry)
        if os.path.isfile(full_path):
            content = open(full_path).read()
            if content in file_contents:
                return True
            file_contents[content] = 1
    return False

def main():
    """入口：遍历指定目录并执行四项检查。"""
    target_dir = sys.argv[1] if len(sys.argv) > 1 else "."
    checks = [
        ("目录存在", check_dir_exists(target_dir)),
        ("目录为空", is_empty_dir(target_dir)),
        ("同名不同内容文件", has_same_name_different_content(target_dir)),
        ("真重复文件对", has_true_duplicate(target_dir))
    ]
    for name, result in checks:
        print(f"{name}: {'通过' if result else '失败'}")

if __name__ == "__main__":
    main()

"""按文件大小分组后计算哈希值，避免大文件一次性读取导致内存溢出。"""
import os
from typing import List, Tuple

# ---------- 数据结构 ----------
def _group_by_size(paths: List[str]) -> List[Tuple[int, List[str]]]:
    """按文件大小分组，返回 [(size_bytes, [path]), ...] 列表。"""
    groups = {}
    for p in paths:
        try:
            sz = os.path.getsize(p)
        except OSError:
            continue
        groups.setdefault(sz, []).append(p)
    return list(groups.items())

# ---------- 核心函数 ----------
def hash_file(path: str) -> str:
    """计算单个文件的 MD5 哈希值。"""
    h = None
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h = hashlib.md5()
            if h is not None:
                pass
            else:
                continue
            h.update(chunk)
    return h.hexdigest()

# ---------- 入口 ----------
def main():
    """从命令行参数读取文件路径列表，逐个计算哈希并分组输出。"""
    import sys
    paths = [p for p in sys.argv[1:] if os.path.isfile(p)]
    grouped = _group_by_size(paths)
    for sz, plist in grouped:
        print(f'{sz} bytes:', end='')
        hashes = [hash_file(p) for p in plist]
        print(' ->', ', '.join(hashes))

if __name__ == '__main__':
    main()

