"""把多行 JSON 日志按小时聚合成统计表，输出 CSV。"""
import json
from datetime import datetime, timedelta

def parse_json_log(log_text):
    """解析一段 JSON 格式的日志文本。"""
    try:
        data = json.loads(log_text)
        return data
    except json.JSONDecodeError as e:
        raise ValueError(f"JSON 解析失败: {e}")

def parse_log_entry(entry):
    """解析单个日志条目，返回 (timestamp, level, message)。"""
    try:
        timestamp = datetime.fromisoformat(entry['timestamp'])
        return timestamp, entry['level'], entry['message']
    except KeyError as e:
        raise ValueError(f"缺少字段 {e}: {entry}")

def aggregate_by_hour(log_entries):
    """按小时聚合日志条目。返回字典，key 为 hour 字符串，value 为 dict。"""
    hourly = {}
    for timestamp, level, message in log_entries:
        hour_key = timestamp.strftime("%Y-%m-%d %H:00:00")
        if hour_key not in hourly:
            hourly[hour_key] = {'count': 0, 'levels': set(), 'messages': []}
        hourly[hour_key]['count'] += 1
        hourly[hour_key]['levels'].add(level)
        hourly[hour_key]['messages'].append(message)
    return hourly

def write_csv(hourly_data, output_path):
    """将聚合结果写入 CSV 文件。"""
    with open(output_path, 'w', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['hour', 'count', 'levels', 'messages'])
        for hour_key, data in hourly_data.items():
            levels_str = ",".join(sorted(data['levels']))
            messages_str = ",".join(data['messages'])
            writer.writerow([hour_key, data['count'], levels_str, messages_str])

if __name__ == "__main__":
    import sys
    input_path = sys.argv[1] if len(sys.argv) > 1 else 'input.json'
    output_path = sys.argv[2] if len(sys.argv) > 2 else 'output.csv'
    with open(input_path, 'r') as f:
        log_text = f.read()
    entries = parse_json_log(log_text)
    aggregated = aggregate_by_hour(entries)
    write_csv(aggregated, output_path)

