"""生成文档的脚本：路由带路径参数、嵌套路由、同名方法不同路径。"""
import re
from typing import List, Tuple, Optional

class DocumentGenerator:
    def __init__(self):
        self.routes = []
        self.methods = {}

    def add_route(self, path: str, method: str) -> None:
        """添加路由。"""
        self.routes.append((path, method))
        self.methods[method] = self.routes[-1]

    def add_method(self, path: str, method: str) -> None:
        """为路径添加方法。"""
        if (path, method) not in self.routes:
            self.routes.append((path, method))
            self.methods[method] = self.routes[-1]

    def match_route(self, path: str) -> Optional[Tuple[str, str]]:
        """匹配路由。"""
        for route in self.routes:
            if re.match(route[0], path):
                return route
        return None

    def generate_document(self, path: str) -> str:
        """生成文档。"""
        matched = self.match_route(path)
        if not matched:
            return "No matching route found."
        method, _ = matched
        doc = f"Document for {path} using {method}"
        return doc


def main():
    generator = DocumentGenerator()
    generator.add_route("/user/{id}", "GET")
    generator.add_route("/user", "POST")
    generator.add_method("/api/v1/users", "PUT")

    print(generator.generate_document("/user/123"))
    print(generator.generate_document("/user"))
    print(generator.generate_document("/api/v1/users"))


