"""扫描目录下的重复文件（按内容哈希），支持 --dry-run 与 --json 输出。"""
import argparse
import hashlib
import os
import sys
from pathlib import Path

def compute_hash(filepath):
    """计算文件的 SHA-256 哈希值。"""
    h = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest()

def find_duplicates(root_dir):
    """查找根目录下所有重复文件（按内容哈希）。返回 {hash: [path]}。"""
    root = Path(root_dir).resolve()
    groups = {}
    for path in root.rglob('*'):
        if path.is_file():
            hash_val = compute_hash(path)
            groups.setdefault(hash_val, []).append(str(path.relative_to(root)))
    return groups

def main(argv):
    parser = argparse.ArgumentParser(description='扫描目录下的重复文件（按内容哈希）。')
    parser.add_argument('directory', help='要扫描的根目录。')
    parser.add_argument('--dry-run', action='store_true', help='不实际删除，仅显示将要操作的内容。')
    parser.add_argument('--json', action='store_true', help='以 JSON 格式输出结果。')
    args = parser.parse_args(argv)

    groups = find_duplicates(args.directory)
    if not groups:
        print(json.dumps({'duplicates': []}, indent=2))
        return

    output = {}
    for hash_val, paths in groups.items():
        if len(paths) > 1:
            output[hash_val] = paths

    if args.json:
        print(json.dumps(output, indent=2, ensure_ascii=False))
    else:
        for hash_val, paths in output.items():
            print(f"哈希值: {hash_val}")
            for path in paths:
                print(f"  - {path}")

if __name__ == '__main__':
    main(sys.argv[1:])

"""优化大文件哈希计算：按大小分组后只对同尺寸文件算哈希。"""
import os
from collections import defaultdict

def group_by_size(file_paths):
    groups = defaultdict(list)
    for path in file_paths:
        size = os.path.getsize(path)
        groups[size].append(path)
    return groups

def hash_file_group(group, algorithm='md5'):
    hashes = []
    for path in group:
        h = hashlib.md5()
        with open(path, 'rb') as f:
            while True:
                chunk = f.read(8192)
                if not chunk:
                    break
                h.update(chunk)
        hashes.append(h.hexdigest())
    return hashes

def main():
    files = []
    for root, _, filenames in os.walk('.'):
        for name in filenames:
            if name.endswith('.txt'):
                files.append(os.path.join(root, name))
    groups = group_by_size(files)
    all_hashes = []
    for size, paths in groups.items():
        hashes = hash_file_group(paths)
        all_hashes.extend(hashes)
    print(all_hashes)

if __name__ == '__main__':
    main()

