# 数据结构：每条记录包含时间戳、主机名和日志内容。
LOG_STRUCTURE = {
    "timestamp": str,
    "hostname": str,
    "message": str
}


def parse_log_line(line):
    """解析单行日志，返回 dict。"""
    parts = line.split("|")
    if len(parts) < 3:
        return None
    try:
        ts_str, host, msg = parts[0], parts[1], parts[2]
        dt = datetime.strptime(ts_str, "%Y-%m-%d %H:%M:%S")
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return {"timestamp": dt,"hostname": host,"message": msg}
    except Exception:
        return None


def aggregate_by_date(logs):
    """按日期聚合日志，返回 dict。"""
    result = {}
    for entry in logs:
        if entry is None:
            continue
        date_key = entry["timestamp"].date()
        if date_key not in result:
            result[date_key] = []
        result[date_key].append(entry)
    return result


def format_result(result):
    """将聚合结果转换为 JSON 字符串。"""
    output = {}
    for date, entries in result.items():
        output[str(date)] = [{"hostname": e["hostname"],"message": e["message"]} for e in entries]
    return json.dumps(output)


def main():
