"""日志聚合脚本：按时间范围和关键词过滤日志行并输出汇总。"""
import sys
from datetime import datetime

# 日志结构定义：每条记录包含时间戳、级别、消息内容。
LOG_STRUCTURE = {
    "timestamp": str,
    "level": str,
    "message": str
}

class LogAggregator:
    def __init__(self, start_time: datetime, end_time: datetime):
        self.start_time = start_time
        self.end_time = end_time

    def filter_logs(self, log_lines: list) -> list:
        """过滤日志行：时间范围 + 关键词匹配。"""
        filtered = []
        for line in log_lines:
            # 解析每行日志（格式：timestamp level message）
            parts = line.split(" ", 2)
            if len(parts) < 3:
                continue
            timestamp_str, level, message = parts[0], parts[1], " ".join(parts[2:])
            try:
                ts = datetime.fromisoformat(timestamp_str.replace("Z", "+00:00"))
            except ValueError:
                continue
            if self.start_time <= ts <= self.end_time and level in ("INFO", "WARNING", "ERROR"):
                # 关键词过滤：message 中包含指定关键字（不区分大小写）
                keyword = "error"
                if keyword.lower() in message.lower():
                    filtered.append(line)
        return filtered

    def aggregate(self, log_lines: list) -> dict:
        """按级别统计日志数量。"""
        counts = {}
        for line in self.filter_logs(log_lines):
            parts = line.split(" ", 2)
            level = parts[1]
            counts[level] = counts.get(level, 0) + 1
        return counts


def main():
    # 读取日志文件
    try:
        with open(sys.argv[1], "r", encoding="utf-8") as f:
            log_lines = [line.rstrip("\n") for line in f]
    except Exception as e:
        print(f"读取日志失败: {e}", file=sys.stderr)
        sys.exit(1)

    # 解析时间范围（命令行参数：start_time end_time）
    try:
        start_str, end_str = sys.argv[2], sys.argv[3]
        start_time = datetime.fromisoformat(start_str.replace("Z", "+00:00"))
        end_time = datetime.fromisoformat(end_str.replace("Z", "+00:00"))
    except Exception as e:
        print(f"解析时间范围失败: {e}", file=sys.stderr)
        sys.exit(1)

    # 执行聚合
    aggregator = LogAggregator(start_time, end_time)
    result = aggregator.aggregate(log_lines)

    # 输出结果（JSON 格式）
    import json
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()

