"""扫描目录下重复文件（按内容哈希），支持 --dry-run 与 --json 输出。"""
import argparse
import hashlib
import os
from pathlib import Path

def get_file_hash(file_path):
    """计算文件的 SHA-256 哈希值。"""
    sha256 = hashlib.sha256()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            sha256.update(chunk)
    return sha256.hexdigest()


def find_duplicates(directory):
    """返回 (hash, list_of_files) 的字典。"""
    dir_path = Path(directory).resolve()
    files_by_hash = {}
    for root, _, filenames in os.walk(dir_path):
        for filename in filenames:
            file_path = Path(root) / filename
            if not file_path.is_file():
                continue
            try:
                h = get_file_hash(file_path)
            except (OSError, IOError):
                continue
            files_by_hash.setdefault(h, []).append(str(file_path))
    return files_by_hash


def main(args):
    """主入口。"""
    directory = args.directory
    dry_run = args.dry_run
    output_format = args.output
    if not os.path.isdir(directory):
        print(f'错误：目录不存在 {directory}')
        return 1
    result = find_duplicates(directory)
    duplicates = {h: files for h, files in result.items() if len(files) > 1}
    if not duplicates:
        print('未发现重复文件。')
        return 0
    if output_format == 'json':
        import json
        print(json.dumps(duplicates, indent=2))
    else:
        for h, files in duplicates.items():
            print(f'哈希 {h[:16]}...：')
            for f in sorted(files):
                print(f'  {f}')


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description='扫描目录下重复文件。')
    parser.add_argument('directory', help='要扫描的目录路径')
    parser.add_argument('--dry-run', action='store_true', help='仅打印计划，不实际执行')
    parser.add_argument('--json', dest='output_format', choices=['json'], default=None, help='以 JSON 格式输出结果')
    args = parser.parse_args()
    main(args)

"""大文件分块哈希工具：按大小分组后对同尺寸文件算哈希，避免单次读取全量数据。
"""
import os
from typing import Dict, List, Tuple

# 1. 导入

# 2. 数据结构
class HashGroup:
    def __init__(self, size: int):
        self.size = size
        self.hashes: List[str] = []

# 3. 核心函数

def group_by_size(file_paths: List[str]) -> Dict[int, HashGroup]:
    """按文件大小分组。"""
    groups: Dict[int, HashGroup] = {}
    for path in file_paths:
        try:
            size = os.path.getsize(path)
        except OSError:
            continue
        if size not in groups:
            groups[size] = HashGroup(size)
        groups[size].hashes.append(os.path.basename(path))
    return groups

def hash_file_group(group: HashGroup) -> str:
    """对组内文件算哈希。"""
    result = []
    for path in group.hashes:
        try:
            with open(path, 'rb') as f:
                chunk_size = 65536
                while True:
                    data = f.read(chunk_size)
                    if not data:
                        break
                    result.append(hashlib.md5(data).hexdigest())
        except OSError:
            continue
    return "\n".join(result)

# 4. 入口

def main():
    import sys
    file_paths = sys.argv[1:]
    groups = group_by_size(file_paths)
    for size, group in groups.items():
        print(f"大小 {size} 的文件：")
        print(hash_file_group(group))

if __name__ == "__main__":
    main()

