def parse_date(date_str):
    """将日期字符串解析为 datetime 对象，兼容多种格式。"""
    for fmt in ("%Y-%m-%d", "%Y/%m/%d", "%d-%m-%Y", "%d/%m/%Y"):
        try:
            return datetime.strptime(date_str, fmt)
        except ValueError:
            continue
    raise ValueError(f"无法解析日期: {date_str}")

def parse_amount(amount_str):
    """将金额字符串解析为浮点数，兼容千分位。"""
    try:
        return float(amount_str.replace("\u00a0", ""))
    except ValueError:
        raise ValueError(f"无法解析金额: {amount_str}")

def clean_row(row):
    """清洗单行数据，返回过滤后的字典。"""
    result = {}
    for key, value in row:
        if value is None or str(value).strip() == "":
            continue
        try:
            if key.lower().startswith("date"):
                result[key] = parse_date(str(value))
            elif key.lower().startswith("amount"):
                result[key] = parse_amount(str(value))
        except ValueError as e:
            print(f"警告: {key} 处理失败: {e}")
