"""实现一个高并发服务类 Service，包含以下方法：

1. __init__(self, data: dict = None): 初始化数据存储，默认使用空字典，若传入非 dict 类型则抛出 TypeError。
2. get(self, key: str) -> Any: 根据键返回对应的值，若键不存在或值为 None 则返回 None。
3. set(self, key: str, value: Any) -> bool: 设置键值对，返回 True 表示成功设置，False 表示键已存在（覆盖不视为新键）。
4. get_all(self) -> dict: 返回当前所有键值对的副本，不修改原数据。
5. update_data(self, data: dict) -> None: 用传入的字典替换内部存储的所有数据。

"""
import threading
from typing import Any, Dict

class Service:
    def __init__(self, data: Dict = None):
        if data is not None and not isinstance(data, dict):
            raise TypeError("data 必须是 dict 类型")
        self._lock = threading.Lock()
        self._data = data if data is not None else {}

    def get(self, key: str) -> Any:
        with self._lock:
            return self._data.get(key)

    def set(self, key: str, value: Any) -> bool:
        with self._lock:
            if key in self._data:
                return False
            self._data[key] = value
            return True

    def get_all(self) -> Dict:
        with self._lock:
            return dict(self._data)

    def update_data(self, data: Dict) -> None:
        with self._lock:
            if not isinstance(data, dict):
                raise TypeError("传入的 data 必须是 dict 类型")
            self._data = data

