"""扫描目录下重复文件（按内容哈希），支持 --dry-run 与 --json 输出。"""
import argparse
import hashlib
import os
import sys
from pathlib import Path

def compute_hash(filepath):
    """计算文件的 SHA-256 哈希值。"""
    h = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest()


def find_duplicates(root_dir):
    """返回 (hash, list_of_files) 的字典。"""
    root = Path(root_dir).resolve()
    if not root.exists():
        raise FileNotFoundError(f'目录不存在: {root}')

    hash_to_files = {}
    for path in root.rglob('*'):
        if path.is_file():
            h = compute_hash(path)
            hash_to_files.setdefault(h, []).append(str(path))

    duplicates = {h: files for h, files in hash_to_files.items() if len(files) > 1}
    return duplicates


def main(argv):
    """命令行入口。"""
    parser = argparse.ArgumentParser(description='扫描目录下重复文件（按内容哈希）。')
    parser.add_argument('directory', help='要扫描的目录路径')
    parser.add_argument('--dry-run', action='store_true', help='不实际删除，仅列出重复项。')
    parser.add_argument('--json', action='store_true', help='以 JSON 格式输出。')

    args = parser.parse_args(argv[1:])

    duplicates = find_duplicates(args.directory)

    if not duplicates:
        print(json.dumps({'message': '未发现重复文件'}))
        return

    output = {}
    for h, files in duplicates.items():
        output[h] = sorted(files)

    if args.json:
        print(json.dumps(output, indent=2, ensure_ascii=False))
    else:
        for h, files in output.items():
            print(f'哈希: {h}')
            for f in files:
                print(f'  {f}')


if __name__ == '__main__':
    main(sys.argv[1:])

"""测试工具：验证目录中是否存在同名不同内容或真重复的子目录。"""
import os
import sys
from pathlib import Path


def check_duplicate_directories(root_dir: str) -> list:
    """检查根目录下是否存在同名不同内容或真重复的子目录。返回列表，包含每个重复组的主路径。"""
    root = Path(root_dir).resolve()
    if not root.exists():
        return []

    # 收集所有直接子目录
    subdirs = [p for p in root.iterdir() if p.is_dir()]
    if not subdirs:
        return []

    # 按名称分组
    groups: dict[str, list[Path]] = {}
    for d in subdirs:
        name = d.name
        groups.setdefault(name, []).append(d)

    duplicates = []
    for name, paths in groups.items():
        if len(paths) < 2:
            continue
        # 检查是否真重复：所有子目录内容完全相同
        first_path = paths[0]
        all_same = True
        for other_path in paths[1:]:
            if not compare_directories(first_path, other_path):
                all_same = False
                break
        # 如果不是真重复，则视为同名不同内容
        if not all_same:
            duplicates.append(str(root / name))
    return duplicates


def compare_directories(dir1: Path, dir2: Path) -> bool:
    """比较两个目录的内容是否完全相同。返回 True 表示相同，False 表示不同。"""
    if dir1 == dir2:
        return True
    # 获取所有文件和子目录的相对路径集合
    def collect_entries(path: Path) -> set[str]:
        entries = set()
        for item in path.rglob('*'):
            if item.is_file():
                entries.add(str(item.relative_to(path)))
            elif item.is_dir():
                entries.add(str(item.relative_to(path)))
        return entries

    entries1 = collect_entries(dir1)
    entries2 = collect_entries(dir2)
    return entries1 == entries2


def main() -> None:
    """入口函数：解析命令行参数，调用 check_duplicate_directories 并输出结果。"""
    if len(sys.argv) != 3:
        print(f"用法: {sys.argv[0]} <根目录> <期望重复组数量>")
        sys.exit(1)

    root_dir = sys.argv[1]
    expected_count = int(sys.argv[2])

    duplicates = check_duplicate_directories(root_dir)
    print(f"找到 {len(duplicates)} 个重复组（期望：{expected_count}）")
    for dup in duplicates:
        print(dup)


if __name__ == "__main__":
    main()

"""清洗脚本：读取 CSV、按日期范围过滤、去除表头与空值、保留金额字段并格式化千分位。"""
import csv
from datetime import datetime

def parse_date(s):
    """尝试解析日期字符串，返回 datetime 或 None。"""
    for fmt in ('%Y-%m-%d', '%Y/%m/%d', '%Y.%m.%d'):
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            continue
    return None

def load_rows(path):
    """读取 CSV，返回 (header, rows) 列表。"""
    with open(path, newline='', encoding='utf-8') as f:
        reader = csv.reader(f)
        header = next(reader)
        return header, list(reader)

def clean_rows(header, rows):
    """清洗行：跳过空值、去除表头列。"""
    cleaned = []
    for row in rows:
        if not any(row):  # 全空
            continue
        new_row = []
        for i, val in enumerate(row):
            if header[i] == 'date':
                d = parse_date(val)
                if d is None or d < start_date:
                    continue
                new_row.append(d.strftime('%Y-%m-%d'))
            elif header[i] == 'amount':
                s = val.strip()
                if not s:
                    continue
                try:
                    num = float(s.replace(',', ''))
                    new_row.append(f"{num:,.2f}")
                except ValueError:
                    continue
            else:
                new_row.append(val)
        cleaned.append(new_row)
    return cleaned

def main():
    """入口：读取、清洗、输出。"""
    path = 'data.csv'
    header, rows = load_rows(path)
    start_date = datetime(2023, 1, 1).date()
    cleaned = clean_rows(header, rows)
    with open('output.csv', 'w', newline='', encoding='utf-8') as f:
        writer = csv.writer(f)
        writer.writerow([h for h in header if h != 'date'])
        for row in cleaned:
            writer.writerow(row)

if __name__ == '__main__':
    main()

