"""日志聚合器：按时间、级别和主机名过滤并输出汇总行。"""
import sys
from datetime import datetime, timezone

class LogEntry:
    def __init__(self, line):
        self.line = line.strip()
        # 解析时间戳（ISO-8601），若无法解析则设为 None
        try:
            ts_str = self.line.split(' ', 2)[0]
            if 'T' in ts_str:
                self.ts = datetime.fromisoformat(ts_str)
            else:
                self.ts = None
        except Exception:
            self.ts = None
        # 解析日志级别（忽略前导空格）
        try:
            level_part = self.line.split(' ', 1)[1] if ' ' in self.line else ''
            self.level = level_part.strip().upper()
        except Exception:
            self.level = 'UNKNOWN'

class LogAggregator:
    def __init__(self, lines):
        # 按时间、级别和主机名分组，返回 dict[(ts, level, host)] -> list[str]
        self.groups = {}
        for entry in lines:
            if not entry.line or entry.ts is None:
                continue
            try:
                ts = entry.ts.isoformat()
            except Exception:
                ts = str(entry.ts)
            level = entry.level
            host = self._extract_host(entry.line, level)
            key = (ts, level, host)
            if key not in self.groups:
                self.groups[key] = []
            self.groups[key].append(entry.line)

    def _extract_host(self, line, level):
        # 主机名是日志行中第一个非空格字符到下一个空格之间的内容
        parts = line.split(' ', 1)
        if len(parts) < 2:
            return 'UNKNOWN'
        host_part = parts[0].split(' ', 1)[-1] if ' ' in parts[0] else parts[0]
        # 若主机名包含特殊字符则保留原样
        return host_part.strip()

    def aggregate(self):
        # 对每个分组输出汇总行："时间,级别,主机名,计数,日志内容"
        result = []
        for (ts, level, host), lines in self.groups.items():
            count = len(lines)
            summary_line = f"{ts},{level},{host},{count},"
            # 追加所有日志行（用换行符分隔）
            result.append(summary_line + '\n' + '\n'.join(lines))
        return result

    def print_result(self):
        for line in self.aggregate():
            sys.stdout.write(line)

if __name__ == '__main__':
    lines = [l.strip() for l in sys.stdin if l.strip()]
    aggregator = LogAggregator(lines)
    aggregator.print_result()

