"""扫描目录下的重复文件（按内容哈希），支持 --dry-run 与 --json 输出。"""
import argparse
import hashlib
import os
import sys


def compute_hash(filepath):
    """计算文件的 SHA-256 哈希值。"""
    sha256 = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            sha256.update(chunk)
    return sha256.hexdigest()


def find_duplicates(directory):
    """查找目录下所有重复文件（按内容哈希）。返回 (hash, list_of_files)。"""
    hash_to_files = {}
    for root, _, files in os.walk(directory):
        for file in files:
            path = os.path.join(root, file)
            try:
                h = compute_hash(path)
            except (OSError, IOError) as e:
                print(f"警告: 无法读取 {path}: {e}", file=sys.stderr)
                continue
            hash_to_files.setdefault(h, []).append(path)
    return hash_to_files


def format_output(data):
    """格式化输出结果。data 为 {(hash, [paths])，返回字符串列表。"""
    result = []
    for h, paths in data.items():
        if len(paths) > 1:
            result.append(f"{h}: {' | '.join(paths)}")
    return result


def main(argv=None):
    """命令行入口。"""
    parser = argparse.ArgumentParser(description='扫描目录下的重复文件（按内容哈希）。')
    parser.add_argument('directory', help='要扫描的目录路径')
    parser.add_argument('--dry-run', action='store_true', help='不实际删除，仅显示将要操作的文件。')
    parser.add_argument('--json', action='store_true', help='以 JSON 格式输出。')
    args = parser.parse_args(argv)

    if not os.path.isdir(args.directory):
        print(f"错误: {args.directory} 不是有效目录", file=sys.stderr)
        sys.exit(1)

    data = find_duplicates(args.directory)
    output_lines = format_output(data)

    if args.json:
        import json
        result = [json.loads(line) for line in output_lines]
        print(json.dumps(result, indent=2))
    else:
        for line in output_lines:
            print(line)


