"""大文件哈希优化器：按大小分组后只对同尺寸文件算哈希，避免全量读取。"""
import os
from collections import defaultdict

def hash_file(path):
    """计算单个文件的 MD5 哈希。"""
    import hashlib
    h = hashlib.md5()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest(), len(os.path.getsize(path))

def group_by_size(file_list):
    """按文件大小分组，返回 {尺寸: [路径]}。"""
    groups = defaultdict(list)
    for path in file_list:
        try:
            size = os.path.getsize(path)
        except OSError:
            continue
        groups[size].append(path)
    return dict(groups)

def process_files(file_paths):
    """主流程：分组后只对同尺寸文件算哈希。"""
    grouped = group_by_size(file_paths)
    results = []
    for size, paths in sorted(grouped.items()):
        hashes = [hash_file(p) for p in paths]
        results.append((size, [(p, h[0]) for p, h in hashes]))
    return results

def main():
    """入口：读取目录下所有 .txt 文件。"""
    import sys
    dir_path = sys.argv[1] if len(sys.argv) > 1 else '.'
    file_paths = [os.path.join(dir_path, f) for f in os.listdir(dir_path) if f.endswith('.txt')]
    results = process_files(file_paths)
    for size, items in results:
        print(f"尺寸 {size}：{len(items)} 个文件")
        for path, h in items:
            print(f"  {path}: {h}")

if __name__ == '__main__':
    main()

