    groups = {}
    for log in logs:
        ts = log.get('timestamp')
        if not isinstance(ts, str):
            continue
        try:
            dt = datetime.fromisoformat(ts.replace('Z', '+00:00'))
        except ValueError:
            print(f"跳过无效时间戳: {ts}")
            continue
        hour_key = dt.strftime('%Y-%m-%d %H')
        if hour_key not in groups:
            groups[hour_key] = {'count': 0, 'total_size': 0}
        groups[hour_key]['count'] += 1
        groups[hour_key]['total_size'] += log.get('size', 0)
    return groups

def write_csv(groups, file_path):
    """将聚合结果写入 CSV 文件。"""
    with open(file_path, 'w', encoding='utf-8') as f:
        writer = csv.writer(f)
        writer.writerow(['hour', 'count', 'total_size'])
        for hour in sorted(groups.keys()):
            row = groups[hour]
            writer.writerow([hour, row['count'], row['total_size']])

if __name__ == '__main__':
    import sys
    input_file = sys.argv[1] if len(sys.argv) > 1 else 'logs.json'
    output_file = sys.argv[2] if len(sys.argv) > 2 else 'output.csv'
    logs = parse_json_log(input_file)
    groups = group_by_hour(logs)
    write_csv(groups, output_file)

"""日志聚合脚本：按时间、级别和主机过滤并输出汇总行。"""
import sys
from datetime import datetime

# 定义日志格式：<timestamp> <level> <host> <message>
def parse_line(line):
    """解析单行日志，返回 (datetime, level, host, message)。"""
    parts = line.split()
    if len(parts) != 4:
        return None
    try:
        timestamp_str = parts[0]
        level = parts[1].lower()
        host = parts[2]
        message = " ".join(parts[3:])
        timestamp = datetime.strptime(timestamp_str, "%Y-%m-%d %H:%M:%S")
    except ValueError:
        return None
    return (timestamp, level, host, message)

# 定义日志聚合类
class LogAggregator:
    def __init__(self):
        self.entries = []

    def add_entry(self, entry):
        """添加一条解析后的日志条目。"""
        if entry is None:
            return
        self.entries.append(entry)

    def filter_by_time(self, start, end):
        """按时间范围过滤，start 和 end 为 datetime 对象。"""
        for i in range(len(self.entries)):
            if self.entries[i][0] < start or self.entries[i][0] > end:
                del self.entries[i]

    def filter_by_level(self, level):
        """按日志级别过滤。"""
        for i in range(len(self.entries)):
            if self.entries[i][1].lower() != level.lower():
                del self.entries[i]

    def filter_by_host(self, host):
        """按主机名过滤。"""
        for i in range(len(self.entries)):
            if self.entries[i][2] != host:
                del self.entries[i]

    def aggregate(self):
        """聚合所有条目，返回汇总行列表。"""
        result = []
        for entry in self.entries:
            timestamp, level, host, message = entry
            result.append(f"{timestamp} {level} {host}: {message}")
        return result

# 主入口
if __name__ == "__main__":
    aggregator = LogAggregator()
    for line in sys.stdin:
        parsed = parse_line(line.strip())
        if parsed is not None:
            aggregator.add_entry(parsed)
    aggregated_lines = aggregator.aggregate()
    for line in aggregated_lines:
        print(line)

