    params: Vec<String>,
};

"impl Router {
    fn new(path: String, method: u8, params: Vec<String>) -> Self {
        Router { path, method, params }
    }
}

"fn parse_routes(input: &str) -> Vec<Router> {
    let mut routes = Vec::new();
    for line in input.lines() {
        if line.starts_with("GET ") || line.starts_with("POST ") {
            let parts: Vec<&str> = line.split_whitespace().collect();
            let path = parts[1].to_string();
            let method = match parts[0] {
                "GET" => 0,
                "POST" => 1,
                _ => -1,
            };
            routes.push(Router::new(path.to_string(), method, Vec::new()));
        }
    }
    routes
}

"""扫描目录下重复文件（按内容哈希），支持 --dry-run 与 --json 输出。"""
import argparse
import hashlib
import json
import os
from pathlib import Path

def compute_hash(filepath):
    """计算文件的 SHA-256 哈希值。"""
    h = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest()


def find_duplicates(root_dir, dry_run=False, json_output=False):
    """查找根目录下重复的文件。"""
    files = {}
    for path in root_dir.rglob('*'):
        if path.is_file():
            rel_path = path.relative_to(root_dir)
            h = compute_hash(path)
            if h in files:
                files[h].append(str(rel_path))
            else:
                files[h] = [str(rel_path)]
    return {h: paths for h, paths in files.items() if len(paths) > 1}


def main():
    parser = argparse.ArgumentParser(description='查找目录下重复文件')
    parser.add_argument('directory', help='要扫描的根目录')
    parser.add_argument('--dry-run', action='store_true', help='不实际删除，仅显示将要操作的内容')
    parser.add_argument('--json', action='store_true', help='以 JSON 格式输出结果')
    args = parser.parse_args()

    duplicates = find_duplicates(args.directory, dry_run=args.dry_run, json_output=args.json)
    if json_output:
        print(json.dumps(duplicates, indent=2))
    else:
        for h, paths in duplicates.items():
            print(f"哈希值: {h}")
            for p in paths:
                print(p)

if __name__ == '__main__':
    main()

"""测试工具：检查目录是否存在、是否为空、是否有同名不同内容或真重复的子目录。"""
def check_dir(dir_path):
    """检查目录是否存在且非空。"""
    import os
    if not os.path.isdir(dir_path):
        return False, "目录不存在"
    try:
        entries = os.listdir(dir_path)
    except Exception as e:
        return False, f"读取目录失败: {e}"
    if len(entries) == 0:
        return True, "空目录"
    return True, "非空目录"
def check_same_name_diff_content(dir_path):
    """检查是否存在同名不同内容的子目录。"""
    import os
    if not os.path.isdir(dir_path):
        return False, "目录不存在"
    try:
        entries = os.listdir(dir_path)
    except Exception as e:
        return False, f"读取目录失败: {e}"
    for entry in entries:
        if not os.path.isdir(os.path.join(dir_path, entry)):
            continue
        sub_entries = os.listdir(os.path.join(dir_path, entry))
        if len(sub_entries) == 0:
            return False, "子目录为空"
    return True, "无同名不同内容子目录"
def check_true_duplicate(dir_path):
    """检查是否存在真重复的子目录。"""
    import os
    if not os.path.isdir(dir_path):
        return False, "目录不存在"
    try:
        entries = os.listdir(dir_path)
    except Exception as e:
        return False, f"读取目录失败: {e}"
    seen = set()
    for entry in entries:
        if not os.path.isdir(os.path.join(dir_path, entry)):
            continue
        sub_entries = os.listdir(os.path.join(dir_path, entry))
        content_hash = "|".join(sorted(sub_entries))
        if content_hash in seen:
            return True, f"发现真重复: {entry}"
        seen.add(content_hash)
    return False, "无真重复子目录"
def main():
