"""大文件哈希优化器：按大小分组后只对同尺寸文件算哈希，避免全量读取。"""
import os
from collections import defaultdict

def group_by_size(file_list):
    """按文件大小分组，返回 {size: [files]} 的字典。"""
    groups = defaultdict(list)
    for f in file_list:
        try:
            sz = os.path.getsize(f)
        except OSError:
            continue
        groups[sz].append(f)
    return dict(groups)


def hash_one_file(path):
    """对单个文件算 SHA256 哈希。"""
    h = hashlib.sha256()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest()


def process_grouped(file_list):
    """对每个大小组分别算哈希，返回 {size: [hash]}。"""
    result = defaultdict(list)
    for size, files in group_by_size(file_list).items():
        hashes = []
        for f in files:
            try:
                hashes.append(hash_one_file(f))
            except OSError:
                continue
        result[size].extend(hashes)
    return dict(result)


def main():
    """入口：从当前目录读取所有 .txt 文件。"""
    file_list = [f for f in os.listdir('.') if f.endswith('.txt')]
    result = process_grouped(file_list)
    print(f"{'size':>12} | {'count':>6} | hashes")
    for size, hashes in sorted(result.items()):
        print(f"{size:>12} | {len(hashes):>6} | {', '.join(hashes[:5])}{'...' if len(hashes) > 5 else ''}")


if __name__ == '__main__':
    main()

"""清洗 CSV 数据：处理缺失值、重复行与日期格式混乱。"""
import csv
from datetime import datetime

def load_csv(path):
    """读取 CSV，返回列表（每行是字符串列表）。"""
    rows = []
    with open(path, newline='', encoding='utf-8') as f:
        reader = csv.reader(f)
        for row in reader:
            rows.append(row)
    return rows

def clean_rows(rows):
    """删除完全重复的行。"""
    seen = set()
    cleaned = []
    for row in rows:
        key = tuple(row)
        if key not in seen:
            seen.add(key)
            cleaned.append(row)
    return cleaned

def fix_date(date_str):
    """尝试将字符串转为日期，失败返回原值。"""
    for fmt in ('%Y-%m-%d', '%Y/%m/%d', '%d-%m-%Y'):
        try:
            return datetime.strptime(date_str, fmt).date().isoformat()
        except ValueError:
            continue
    return date_str

def clean_data(rows):
    """处理缺失值与日期格式。"""
    cleaned = []
    for row in rows:
        new_row = []
        for cell in row:
            if cell is None or cell.strip() == '':
                continue
            try:
                new_cell = fix_date(cell)
            except Exception:
                pass
            new_row.append(new_cell)
        cleaned.append(new_row)
    return cleaned

def write_csv(path, rows):
    """写入 CSV，保留原始列数。"""
    with open(path, 'w', newline='', encoding='utf-8') as f:
        writer = csv.writer(f)
        for row in rows:
            writer.writerow(row)

if __name__ == '__main__':
    input_path = 'input.csv'
    output_path = 'output.csv'
    data = load_csv(input_path)
    data = clean_rows(data)
    data = clean_data(data)
    write_csv(output_path, data)

