"""实现一个线程安全的缓存服务，支持并发请求和数据保护。"""
import threading
from typing import Optional, Dict

class ThreadSafeCache:
    def __init__(self):
        self._cache: Dict[str, str] = {}
        self._lock = threading.Lock()

    def get(self, key: str) -> Optional[str]:
        """获取缓存数据。"""
        with self._lock:
            return self._cache.get(key)

    def put(self, key: str, value: str) -> None:
        """设置缓存数据。"""
        with self._lock:
            self._cache[key] = value

    def clear(self) -> None:
        """清空所有缓存数据。"""
        with self._lock:
            self._cache.clear()

# 服务入口
if __name__ == "__main__":
    cache = ThreadSafeCache()
    print(cache.get("test"))
    cache.put("test", "value1")
    print(cache.get("test"))
    cache.clear()

"""把多行 JSON 日志按小时聚合成统计表，输出 CSV。"""
import json
from datetime import datetime, timedelta

def parse_json_log(log_text):
    """解析单行 JSON 字符串。"""
    try:
        return json.loads(log_text)
    except json.JSONDecodeError as e:
        print(f"JSON 解析错误: {e}")
        return None

def parse_log_line(line):
    """把多行日志按行分割。"""
    lines = line.strip().split('\n')
    return [parse_json_log(l) for l in lines]

def aggregate_by_hour(logs):
    """按小时聚合日志数量。"""
    hour_counts = {}
    for log in logs:
        if not isinstance(log, dict):
            continue
        ts = log.get('timestamp')
        if not ts or 'T' not in str(ts):
            continue
        try:
            dt = datetime.fromisoformat(str(ts).replace('Z', '+00:00'))
        except ValueError:
            continue
        hour_key = dt.strftime('%Y-%m-%d %H')
        hour_counts[hour_key] = hour_counts.get(hour_key, 0) + 1
    return hour_counts

def write_csv(hour_counts, filename):
    """把聚合结果写入 CSV。"""
    import csv
    with open(filename, 'w', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['hour', 'count'])
        for hour in sorted(hour_counts.keys()):
            writer.writerow([hour, hour_counts[hour]])

def main():
    """主入口。"""
    import sys
    if len(sys.argv) < 2:
        print("用法: python log_processor.py <input_log.txt>")
        return
    with open(sys.argv[1], 'r') as f:
        lines = f.read()
    logs = parse_log_line(lines)
    if not logs:
        print("未解析到任何日志。")
        return
    hour_counts = aggregate_by_hour(logs)
    output_file = sys.argv[2] if len(sys.argv) > 2 else 'output.csv'
    write_csv(hour_counts, output_file)
    print(f"已生成 {output_file}")

if __name__ == '__main__':
    main()

"""日志聚合脚本：按天汇总日志并输出 JSON。"""
import sys
from datetime import datetime, timezone

# 数据结构：每条记录包含时间戳、主机名和日志内容。
LOG_STRUCTURE = {
    "timestamp": str,
    "hostname": str,
    "message": str
}


def parse_log_line(line: str) -> dict | None:
    """解析单行日志，返回结构化字典或 None（坏行跳过）。"""
    parts = line.split("|")
    if len(parts) != 3:
        return None
    try:
        ts_str, host, msg = parts[0], parts[1], parts[2]
        # 解析时间戳：支持 ISO8601 格式，默认 UTC。
        dt = datetime.fromisoformat(ts_str.replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return {
            "timestamp": dt.isoformat(),
            "hostname": host,
            "message": msg
        }
    except Exception:
        return None


def aggregate_by_day(logs: list[dict]) -> dict[str, list[dict]]:
    """按日期聚合日志，返回 {date_str: [logs]}。"""
    result = {}
    for log in logs:
        # 提取日期部分（YYYY-MM-DD），保留时区信息。
        date_key = log["timestamp"][:10]
        if date_key not in result:
            result[date_key] = []
        result[date_key].append(log)
    return result


def format_output(aggregated: dict) -> str:
    """将聚合结果格式化为 JSON 字符串。"""
    import json
    return json.dumps(aggregated, ensure_ascii=False, indent=2)


def main() -> None:
    """主入口：读取 stdin，按天聚合，输出 JSON。"""
    logs = []
    for line in sys.stdin:
        log = parse_log_line(line.strip())
        if log is not None:
            logs.append(log)

    aggregated = aggregate_by_day(logs)
    output = format_output(aggregated)
    print(output)


