"""扫描目录下的重复文件（按内容哈希），支持 --dry-run 与 --json 输出。"""
import argparse
import hashlib
import os
import sys

def get_file_hash(filepath):
    """计算文件的 SHA256 哈希值。"""
    sha256 = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            sha256.update(chunk)
    return sha256.hexdigest()


def find_duplicates(directory):
    """查找目录下内容相同的文件对。返回字典 {hash: [path]}。"""
    hash_map = {}
    for root, _, files in os.walk(directory):
        for file in files:
            path = os.path.join(root, file)
            try:
                h = get_file_hash(path)
            except (OSError, IOError) as e:
                print(f"警告: 无法读取 {path}: {e}", file=sys.stderr)
                continue
            hash_map.setdefault(h, []).append(path)
    return hash_map


def main():
    parser = argparse.ArgumentParser(description='扫描目录下的重复文件（按内容哈希）。')
    parser.add_argument('directory', help='要扫描的目录路径')
    parser.add_argument('--dry-run', action='store_true', help='仅打印不执行操作')
    parser.add_argument('--json', action='store_true', help='以 JSON 格式输出结果')
    args = parser.parse_args()

    if not os.path.isdir(args.directory):
        print(f"错误: 目录不存在或不是目录: {args.directory}", file=sys.stderr)
        sys.exit(1)

    result = find_duplicates(args.directory)
    duplicates = {h: paths for h, paths in result.items() if len(paths) > 1}

    if args.json:
        print(json.dumps({'duplicates': duplicates}, indent=2))
    else:
        for h, paths in duplicates.items():
            print(f"哈希 {h[:16]}...:")
            for p in paths:
                print(p)

if __name__ == '__main__':
    main()

"""大文件哈希优化器：按大小分组后只对同尺寸文件算哈希，避免全量读取。"""
import os
from collections import defaultdict

def hash_file(path):
    """计算单个文件的 MD5 哈希。"""
    import hashlib
    h = hashlib.md5()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest(), len(os.path.getsize(path))

def group_by_size(files):
    """按文件大小分组，返回 {size_bytes: [paths]}。"""
    groups = defaultdict(list)
    for path in files:
        try:
            size = os.path.getsize(path)
        except OSError:
            continue
        groups[size].append(path)
    return dict(groups)

def main():
    """主入口：读取目录下所有 .py 文件，按大小分组后只对同尺寸文件算哈希。"""
    import sys
    dir_path = sys.argv[1] if len(sys.argv) > 1 else '.'
    files = [f for f in os.listdir(dir_path) if f.endswith('.py')]
