"""清洗脚本：读取 CSV、按日期范围过滤、去除重复行、处理金额格式。"""
import csv
from datetime import datetime, timedelta

def load_csv(path):
    """读取 CSV 并返回列表。"""
    rows = []
    with open(path, newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            rows.append(row)
    return rows

def filter_by_date(rows, start, end):
    """按日期范围过滤。"""
    filtered = []
    for row in rows:
        date_str = row.get('date', '')
        try:
            dt = datetime.strptime(date_str.strip(), '%Y-%m-%d')
        except ValueError:
            continue
        if start <= dt <= end:
            filtered.append(row)
    return filtered

def remove_duplicates(rows):
    """去除重复行。"""
    seen = set()
    unique = []
    for row in rows:
        key = tuple(row.values())
        if key not in seen:
            seen.add(key)
            unique.append(row)
    return unique

def clean_amount(amount):
    """清洗金额：去除千分位和货币符号。"""
    if amount is None or amount == '':
        return ''
    s = str(amount).replace('$', '').replace(',', '')
    try:
        float(s)
        return s
    except ValueError:
        return s.strip()

def main():
    """主入口。"""
    path = input("请输入 CSV 文件路径：")
    rows = load_csv(path)
    start = datetime.strptime(input("起始日期（YYYY-MM-DD）："), '%Y-%m-%d')
    end = datetime.strptime(input("结束日期（YYYY-MM-DD）："), '%Y-%m-%d')
    rows = filter_by_date(rows, start, end)
    rows = remove_duplicates(rows)

    with open('output.csv', 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=rows[0].keys())
        writer.writeheader()
        for row in rows:
            cleaned_row = {k: clean_amount(row.get(k)) if k == 'amount' else row[k] for k in row}
            writer.writerow(cleaned_row)

if __name__ == '__main__':
    main()

