import os
import json
from typing import Optional

class ServiceManager:
    def __init__(self, db_path: str = "data.db") -> None:
        self.db_path = db_path
        self._ensure_db()

    def _ensure_db(self) -> None:
        if not os.path.exists(self.db_path):
            with open(self.db_path, 'w', encoding='utf-8') as f:
                json.dump([], f)

    def create_service(
        self,
        name: str,
        config: dict,
        owner_id: Optional[int] = None
    ) -> bool:
        """创建服务，返回 True 表示成功。"""
        if not isinstance(name, str) or not name.strip():
            return False
        if not isinstance(config, dict):
            return False
        if owner_id is not None and (not isinstance(owner_id, int)):
            return False

        with open(self.db_path, 'r', encoding='utf-8') as f:
            data = json.load(f)

        for item in data:
            if item.get("name") == name:
                return False  # 重复创建冲突

        entry = {
            "name": name,
            "config": config,
            "owner_id": owner_id
        }
        with open(self.db_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
        data.append(entry)
        with open(self.db_path, 'w', encoding='utf-8') as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
        return True

    def delete_service(
        self,
        name: str
    ) -> bool:
        """删除服务，返回 True 表示成功。"""
        if not isinstance(name, str) or not name.strip():
            return False

        with open(self.db_path, 'r', encoding='utf-8') as f:
            data = json.load(f)

        new_data = [item for item in data if item.get("name") != name]
        if len(new_data) == len(data):
            return False  # 删除不存在

        with open(self.db_path, 'w', encoding='utf-8') as f:
            json.dump(new_data, f, ensure_ascii=False, indent=2)
        return True

    def get_service(
        self,
        name: str
    ) -> Optional[dict]:
        """获取服务，返回 None 表示不存在。"""
        if not isinstance(name, str) or not name.strip():
            return None

        with open(self.db_path, 'r', encoding='utf-8') as f:
            data = json.load(f)

        for item in data:
            if item.get("name") == name:
                return item
        return None


