"""把多行 JSON 日志按小时聚合成统计表，输出 CSV。"""
import json
from datetime import datetime, timedelta

def parse_json_log(log_text):
    """解析一段或多段 JSON 日志文本。"""
    entries = []
    for line in log_text.split('\n'):
        if not line.strip():
            continue
        try:
            entry = json.loads(line)
            entries.append(entry)
        except json.JSONDecodeError:
            pass
    return entries

def aggregate_by_hour(entries):
    """按小时聚合日志条目。"""
    hour_buckets = {}
    for entry in entries:
        timestamp = entry.get('timestamp')
        if not isinstance(timestamp, str):
            continue
        try:
            dt = datetime.fromisoformat(timestamp)
        except ValueError:
            continue
        hour_key = dt.strftime('%Y-%m-%d %H:00')
        if hour_key not in hour_buckets:
            hour_buckets[hour_key] = {'count': 0, 'total_bytes': 0}
        hour_buckets[hour_key]['count'] += 1
        # 假设每个条目有 size 字段，累加大小（单位：字节）
        if 'size' in entry:
            try:
                hour_buckets[hour_key]['total_bytes'] += int(entry['size'])
            except (ValueError, TypeError):
                pass
    return hour_buckets

def write_csv(hour_buckets, output_path):
    """将聚合结果写入 CSV 文件。"""
    with open(output_path, 'w', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['hour', 'count', 'total_bytes'])
        for hour_key in sorted(hour_buckets.keys()):
            data = hour_buckets[hour_key]
            writer.writerow([hour_key, data['count'], data['total_bytes']])

if __name__ == '__main__':
    import sys
    input_file = sys.argv[1] if len(sys.argv) > 1 else 'input.log'
    output_file = sys.argv[2] if len(sys.argv) > 2 else 'output.csv'
    with open(input_file, 'r') as f:
        log_text = f.read()
    entries = parse_json_log(log_text)
    hour_buckets = aggregate_by_hour(entries)
    write_csv(hour_buckets, output_file)

