"""扫描目录下的重复文件（按内容哈希），支持 --dry-run 与 --json 输出。"""
import argparse
import hashlib
import os
import sys
from pathlib import Path


def compute_hash(filepath):
    """计算文件的 SHA-256 哈希值。"""
    h = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest()


def find_duplicates(root_dir):
    """查找根目录下所有重复文件（按内容哈希）。返回字典：{hash: [path]}。"""
    hash_map = {}
    for path in Path(root_dir).rglob('*'):
        if path.is_file():
            file_hash = compute_hash(path)
            hash_map.setdefault(file_hash, []).append(str(path))
    return hash_map


def main(argv):
    """命令行入口。"""
    parser = argparse.ArgumentParser(description='扫描目录下的重复文件（按内容哈希）。')
    parser.add_argument('directory', help='要扫描的根目录')
    parser.add_argument('--dry-run', action='store_true', help='仅显示不执行操作')
    parser.add_argument('--json', action='store_true', help='以 JSON 格式输出结果')
    args = parser.parse_args(argv)

    root_dir = Path(args.directory).resolve()
    if not root_dir.is_dir():
        print(f'错误：{root_dir} 不是目录。', file=sys.stderr)
        sys.exit(1)

    hash_map = find_duplicates(root_dir)

    # 按哈希分组，排除同一文件多次出现的重复项
    result = {}
    for h, paths in hash_map.items():
        if len(set(paths)) > 1:
            result[h] = sorted(set(paths))

    if args.json:
        print(json.dumps(result, indent=2, ensure_ascii=False))
    else:
        for h, paths in result.items():
            print(f'哈希: {h}')
            for p in paths:
                print(p)


if __name__ == '__main__':
    main()

"""工具类：大文件分块哈希（按大小分组）"""
import os
from typing import List, Tuple

# ---------- 数据结构 ----------
def _group_by_size(paths: List[str]) -> dict:
    """将路径列表按文件大小分组，返回 {size_bytes: [paths]}。"""
    groups = {}
    for p in paths:
        try:
            sz = os.path.getsize(p)
        except OSError:
            continue
        groups.setdefault(sz, []).append(p)
    return groups

# ---------- 核心函数 ----------
def hash_chunks(paths: List[str]) -> dict:
    """对每个文件做分块哈希，返回 {path: (size_bytes, digest)}。"""
    result = {}
    for p in paths:
        try:
            sz = os.path.getsize(p)
        except OSError:
            continue
        if sz == 0:
            result[p] = (sz, "")
            continue
        # 按大小分组：所有同尺寸文件共享一次哈希计算
        groups = _group_by_size(paths)
        chunk_digest_map = {}
        for size, file_list in groups.items():
            if p not in file_list:
                continue
            h = hashlib.sha256()
            with open(p, "rb") as f:
                while True:
                    data = f.read(65536)
                    if not data:
                        break
                    h.update(data)
            chunk_digest_map[size] = h.hexdigest()
        result[p] = (sz, chunk_digest_map[sz])
    return result

# ---------- 入口 ----------
def main():
    """示例：读取当前目录下所有 .txt 文件。"""
    import glob
    paths = glob.glob("*.txt")
    out = hash_chunks(paths)
    for p, (sz, dig) in out.items():
        print(f"{p}: size={sz}, digest={dig}")

if __name__ == "__main__":
    main()

