import sys
from datetime import datetime, timezone

# 日志行格式：<timestamp> <level> <message>
# 例如：2023-01-01T12:00:00Z INFO "User logged in"
def parse_line(line):
    """解析单行日志，返回 (datetime, level, message)。"""
    parts = line.strip().split()
    if len(parts) < 3:
        return None
    timestamp_str = parts[0]
    level = parts[1].upper()
    message = ' '.join(parts[2:])
    try:
        dt = datetime.fromisoformat(timestamp_str.replace('Z', '+00:00'))
    except ValueError:
        return None
    return (dt, level, message)

