        parsed = parse_line(line)
        if parsed is None:
            continue
        dt, level, message = parsed
        date_str = dt.strftime('%Y-%m-%d')
        entry = []
        entry.append((level, message))
        result.setdefault(date_str, []).append(entry)
    return result

