"""清洗脚本：读取 CSV、按日期范围过滤、去除表头和空值。"""
import csv
from datetime import datetime, timedelta

# 定义日期范围（开始日期、结束日期）
DATE_START = "2023-01-01"
DATE_END = "2023-12-31"


def parse_date(date_str):
    """将字符串转换为 datetime 对象。"""
    try:
        return datetime.strptime(date_str, "%Y-%m-%d")
    except ValueError:
        raise ValueError(f"无效的日期格式：{date_str}")


def filter_by_date(row):
    """根据日期范围过滤行。返回 True 表示保留。"""
    date_str = row["date"] if "date" in row else None
    if not date_str:
        return False
    try:
        date_obj = parse_date(date_str)
        if DATE_START <= date_obj <= DATE_END:
            return True
        return False
    except ValueError:
        return False


def clean_row(row):
    """清洗行：去除表头和空值。"""
    cleaned = {}
    for key, value in row.items():
        if value is None or str(value).strip() == "":
            continue
        cleaned[key] = value.strip()
    return cleaned


def main():
    """主入口：读取 CSV、过滤、清洗并输出。"""
    input_file = "input.csv"
    output_file = "output.csv"

    with open(input_file, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        rows = list(reader)

    filtered_rows = []
    for row in rows:
        if filter_by_date(row):
            cleaned_row = clean_row(row)
            if cleaned_row:
                filtered_rows.append(cleaned_row)

    with open(output_file, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=list(filtered_rows[0].keys()) if filtered_rows else [])
        for row in filtered_rows:
            writer.writerow(row)


