"""清洗 UTF-8 文件中的 BOM 和首列表头。"""
import os
from pathlib import Path

def is_bom(data):
    return data[:3] == "\ufeff"

def strip_bom(text):
    if is_bom(text):
        return text[3:]
    return text

def clean_file(path):
    with open(path, 'r', encoding='utf-8') as f:
        lines = [strip_bom(line) for line in f.readlines()]
    return '\n'.join(lines)

def main():
    path = input("请输入文件路径：")
    result = clean_file(path)
    print(result)

if __name__ == "__main__":
    main()

"""把多行 JSON 日志按小时聚合成统计表，输出 CSV。"""
import json
from datetime import datetime, timedelta

def parse_json_log(log_text):
    """解析 JSON 字符串，返回列表。"""
    return json.loads(log_text)

def group_by_hour(records):
    """按小时分组。"""
    groups = {}
    for record in records:
        hour = datetime.fromisoformat(record['timestamp']).hour
        if hour not in groups:
            groups[hour] = []
        groups[hour].append(record)
    return groups

def to_csv(groups):
    """转成 CSV。"""
    import csv
    with open('output.csv', 'w', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['hour', 'count'])
        for hour in sorted(groups):
            writer.writerow([hour, len(groups[hour])])

if __name__ == '__main__':
    with open('input.jsonl', 'r') as f:
        lines = [f.readline() for _ in range(100)]
        records = parse_json_log(lines)
        groups = group_by_hour(records)
        to_csv(groups)

"""日志聚合脚本：读取本地文件，按行解析并输出统计结果。"""
import os
from collections import defaultdict

# 数据结构：按文件名和行号分组，记录每行的内容与状态.
def parse_line(line):
    """解析单行日志，返回 (line, is_valid) 是否为有效行。"""
    if not line:
        return ("", False)
    # 这里可以扩展更多校验逻辑
    return (line, True)

# 数据结构：按文件名和行号分组，记录每行的内容与状态.
def aggregate_data(data):
    """聚合数据并返回统计结果。"""
    result = defaultdict(list)
    for file_name, lines in data.items():
        for line, is_valid in lines:
            if is_valid:
                result[file_name].append(line)
    return dict(result)

# 核心函数：读取文件并解析日志，返回结构化数据.
def read_and_parse(file_path):
    """读取指定路径的日志文件，按行解析并返回结构化数据。"""
    if not os.path.exists(file_path):
        return {}
    data = defaultdict(list)
    with open(file_path, 'r', encoding='utf-8') as f:
        for line in f:
            file_name, line_content = parse_line(line)
            is_valid, _ = parse_line(line_content)
            data[file_name].append((line_content, is_valid))
    return dict(data)

# 入口：主函数，调用核心函数并输出结果。
def main():
    """主入口，读取日志文件并输出聚合结果。"""
    file_path = 'logs.txt'
    data = read_and_parse(file_path)
    result = aggregate_data(data)
    for file_name, lines in result.items():
        print(f"{file_name}: {len(lines)} valid lines")

if __name__ == "__main__":
    main()

