"""扫描目录下的重复文件（按内容哈希），支持 --dry-run 与 --json 输出。"""
import argparse
import hashlib
import os
import sys
from pathlib import Path


def compute_hash(file_path):
    """计算文件的 SHA-256 哈希值。"""
    sha256 = hashlib.sha256()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            sha256.update(chunk)
    return sha256.hexdigest()


def find_duplicates(root_dir):
    """在根目录下递归查找重复文件。返回字典：{hash: [路径]}。"""
    root = Path(root_dir).resolve()
    hash_map = {}
    for path in root.rglob('*'):
        if path.is_file():
            h = compute_hash(path)
            hash_map.setdefault(h, []).append(str(path))
    return hash_map


def format_output(data, dry_run=False):
    """格式化输出。dry_run 为 True 时只打印将要删除的路径。"""
    if not data:
        print('无重复文件')
        return
    lines = []
    for h, paths in data.items():
        if len(paths) > 1:
            lines.append(f'哈希: {h}')
            for p in sorted(set(paths)):
                lines.append(p)
    print('\n'.join(lines))


def main(argv=None):
    """命令行入口。"""
    parser = argparse.ArgumentParser(description='扫描目录下的重复文件（按内容哈希）。')
    parser.add_argument('directory', help='要扫描的根目录')
    parser.add_argument('--dry-run', action='store_true', help='仅打印将要删除的路径，不实际操作。')
    parser.add_argument('--json', action='store_true', help='以 JSON 格式输出。')
    args = parser.parse_args(argv)

    data = find_duplicates(args.directory)
    if not data:
        print('无重复文件')
        return
    format_output(data, dry_run=args.dry_run)


if __name__ == '__main__':
    main()
